/** Own the definitions and read environments installed in one engine. */
import { logger } from "../utils/logger.js";
import { canonicallyEqual } from "../utils/canonical-json.js";
import { NameResolver } from "../reactions/resolving.js";
import { standardComputations } from "./computations.js";
import { fragmentChannelsOfFormer, fusedFormersOf, viewChannelsOfFormer, viewChannelsOfView, } from "./collection.js";
import { serializeFormer } from "./former-lowering.js";
import { serializeView } from "./view-lowering.js";
import { AuthoredReferenceResolver } from "./authored-reference-resolution.js";
import { ImportedIrBinder } from "./imported-ir-binding.js";
import { ViewFormerValidator } from "./view-former-validation.js";
export class Registry {
    conceptsByName = new Map();
    computationsByName = new Map();
    viewsByName = new Map();
    formersByName = new Map();
    authoredByDeclaration = new WeakMap();
    resolver;
    authored;
    validator;
    binder;
    env;
    constructor() {
        for (const ref of standardComputations) {
            this.computationsByName.set(ref.computationName, ref);
        }
        this.resolver = new NameResolver({
            conceptNamed: (name) => this.conceptNamed(name),
            computationNamed: (name) => this.computationNamed(name),
        });
        this.authored = new AuthoredReferenceResolver(this.resolver, {
            computationNamed: (name) => this.computationNamed(name),
            readEnv: () => this.readEnv(),
        });
        this.validator = new ViewFormerValidator({
            resolver: this.resolver,
            viewNamed: (name) => this.viewNamed(name),
            formerNamed: (name) => this.formerNamed(name),
            resolveAuthoredComputation: (ref, site) => this.authored.resolveComputation(ref, site),
        });
        this.binder = new ImportedIrBinder({
            resolver: this.resolver,
            formerNamed: (name) => this.formerNamed(name),
            assertPatternUsable: (pattern, site, kind) => this.validator.assertPatternUsable(pattern, site, kind),
            assertOpUsable: (op, site, kind) => this.validator.assertOpUsable(op, site, kind),
        });
    }
    get concepts() {
        return this.conceptsByName;
    }
    registerConcept(name, instrumented) {
        const existing = this.conceptsByName.get(name);
        if (existing !== undefined && existing !== instrumented) {
            logger.warn(`Two concepts share the name "${name}" — exported reactions naming it will resolve to the most recently instrumented one.`);
        }
        this.conceptsByName.set(name, instrumented);
    }
    registerComputations(computations) {
        for (const [name, ref] of Object.entries(computations)) {
            if (name !== ref.computationName || ref.source !== "vocabulary") {
                throw new Error(`Computation "${name}" was not declared by this vocabulary.`);
            }
            const existing = this.computationsByName.get(name);
            if (existing !== undefined && existing !== ref) {
                throw new Error(`Computation "${name}" is already installed in this assembly.`);
            }
            this.computationsByName.set(name, ref);
        }
    }
    resolveDeclaration(name, declaration) {
        this.authored.resolveDeclaration(name, declaration);
    }
    indexDeclarationReads(declaration) {
        const fromOps = (ops) => {
            for (const op of ops ?? []) {
                if ((op.op === "find" || op.op === "whether" || op.op === "no") &&
                    op.view !== undefined &&
                    typeof op.view !== "string") {
                    this.indexView(op.view);
                }
            }
        };
        fromOps(declaration.whereOps);
        for (const node of declaration.then) {
            fromOps(node.whereOps);
            fromOps(node.transformOps);
            for (const fused of fusedFormersOf(node.action.input))
                this.indexFormer(fused.former);
        }
    }
    declareViews(...refs) {
        for (const ref of refs)
            this.indexView(ref);
    }
    declareAuthoredViews(...declarations) {
        for (const [ref, authored] of declarations) {
            this.authoredByDeclaration.set(ref, authored);
            this.indexView(ref);
        }
    }
    declareFormers(...refs) {
        for (const ref of refs)
            this.indexFormer(ref);
    }
    declareAuthoredFormers(...declarations) {
        for (const [ref, authored] of declarations) {
            this.authoredByDeclaration.set(ref, authored);
            this.indexFormer(ref);
        }
    }
    registerViews(views) {
        this.binder.assertViewDag(views);
        for (const ir of views) {
            const ref = this.binder.bindView(ir);
            if (ir.authored !== undefined)
                this.authoredByDeclaration.set(ref, ir.authored);
            if (!this.registerUniqueView(ref, ir, false))
                continue;
            this.validator.assertViewUsable(ref);
            this.viewsByName.set(ir.name, ref);
        }
    }
    registerFormers(formers) {
        for (const ir of formers) {
            const ref = this.binder.bindFormer(ir);
            if (ir.authored !== undefined)
                this.authoredByDeclaration.set(ref, ir.authored);
            if (!this.registerUniqueFormer(ref, ir, false))
                continue;
            this.validator.assertFormable(ref);
            this.formersByName.set(ir.name, ref);
        }
    }
    bindReaction(reaction) {
        return this.binder.bindReaction(reaction);
    }
    assertFormable(ref) {
        this.validator.assertFormable(ref);
    }
    formerRefs() {
        return this.formersByName.values();
    }
    formerNamed(name) {
        return this.formersByName.get(name);
    }
    viewRefs() {
        return this.viewsByName.values();
    }
    authoredIdentityOf(ref) {
        return this.authoredByDeclaration.get(ref);
    }
    viewNamed(name) {
        return this.viewsByName.get(name);
    }
    readBackEnv() {
        return {
            queryPromise: (ref) => {
                try {
                    return this.resolver.query(ref.concept, ref.query, "read-back").queryPromise;
                }
                catch {
                    return undefined;
                }
            },
            viewPromise: (name) => this.viewsByName.get(name)?.promise,
        };
    }
    readEnv() {
        this.env ??= {
            query: (ref, site) => this.resolver.query(ref.concept, ref.query, site),
            computation: (name, site) => this.resolver.computation(name, site),
            viewByName: (name, site) => {
                const view = this.viewsByName.get(name);
                if (view === undefined) {
                    throw new Error(`Reaction "${site}": view "${name}" is not registered — ` +
                        "registerViews(...) before the reactions that ask it.");
                }
                return view;
            },
            formerByName: (name, site) => {
                const ref = this.formersByName.get(name);
                if (ref === undefined) {
                    throw new Error(`Former "${site}": spliced fragment "${name}" resolves against ` +
                        "the engine's registered formers — register dependencies first.");
                }
                return ref;
            },
        };
        return this.env;
    }
    conceptNamed(name) {
        return this.conceptsByName.get(name);
    }
    computationNamed(name) {
        return this.computationsByName.get(name);
    }
    indexView(ref) {
        if (!this.registerUniqueView(ref, serializeView(ref), true))
            return;
        for (const channel of viewChannelsOfView(ref)) {
            if (channel.live !== undefined)
                this.indexView(channel.live);
        }
        this.validator.assertViewUsable(ref);
        this.viewsByName.set(ref.viewName, ref);
    }
    indexFormer(ref) {
        if (!this.registerUniqueFormer(ref, serializeFormer(ref), true))
            return;
        for (const channel of viewChannelsOfFormer(ref)) {
            if (channel.live !== undefined)
                this.indexView(channel.live);
        }
        for (const channel of fragmentChannelsOfFormer(ref)) {
            if (channel.live !== undefined)
                this.indexFormer(channel.live);
        }
        this.validator.assertFormable(ref);
        this.formersByName.set(ref.formerName, ref);
    }
    registerUniqueView(candidate, ir, elaborate) {
        return this.registerUnique(this.viewsByName, candidate.viewName, candidate, ir, serializeView, "View", elaborate);
    }
    registerUniqueFormer(candidate, ir, elaborate) {
        return this.registerUnique(this.formersByName, candidate.formerName, candidate, ir, serializeFormer, "Former", elaborate);
    }
    registerUnique(map, name, candidate, candidateIR, serializeExisting, kind, elaborate) {
        const existing = map.get(name);
        if (existing === undefined)
            return true;
        if (existing === candidate)
            return false;
        if (canonicallyEqual(serializeExisting(existing), candidateIR))
            return false;
        const detail = elaborate
            ? ` — two ${kind.toLowerCase()}s may not disagree about what one sentence means.`
            : ".";
        throw new Error(`${kind} "${name}" is already registered with a different definition${detail}`);
    }
}
